	public static final int ROWS = 4096;
	private static final int SUBJECTS = 512;
	private static final int VALUES_PER_SUBJECT = 8;
	private static final int REPEAT_RUN = 32;
	private static final String WRITER_PACKAGE = "org.eclipse.rdf4j.query.resultio.binary.";
	private static final String NS = "urn:binary-benchmark:";
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final List<String> QUERY_NAMES = List.of("s", "label", "kind", "a", "b", "c", "d", "v");
	private static final List<String> WORKLOADS = List.of("ascii", "unicode", "repeat_identity", "repeat_equal_lmdb",
			"unique_lmdb", "wide", "long", "long_unicode", "long_latin1", "long_cjk", "long_emoji", "long_sparse", "medium", "medium_unicode", "query");
	private static final IRI CODE_DATATYPE = VF.createIRI(NS + "datatype:code");
	private static final ValueStoreRevision SYNTHETIC_REVISION = new CanonicalRevision();

	@Param({ "published", "current" })
	public String implementation;

	@Param({ "ascii", "unicode", "repeat_identity", "repeat_equal_lmdb", "unique_lmdb", "wide", "long", "long_unicode", "long_latin1", "long_cjk", "long_emoji", "long_sparse", "medium", "medium_unicode", "query" })
	public String workload;

