	public String namespaceLayout = "stable";

	private Constructor<? extends TupleQueryResultWriter> constructor;
	private boolean heartbeatSink;
	private char iriColumnSeparator;
	private List<String> names;
	private BindingSet[] rows;
	private final ReusableOutput output = new ReusableOutput();
	private Path directory;
	private SailRepository repository;
	private RepositoryConnection connection;
