	@Setup(Level.Trial)
	public void setup() throws Exception {
		if (!WORKLOADS.contains(workload)) {
			throw new IllegalArgumentException("Unknown workload: " + workload);
		}
		iriColumnSeparator = switch (namespaceLayout) {
		case "stable" -> '-';
		case "churn" -> ':';
		default -> throw new IllegalArgumentException("Unknown namespace layout: " + namespaceLayout);
		};
		heartbeatSink = switch (sink) {
		case "memory" -> false;
		case "heartbeat" -> true;
		default -> throw new IllegalArgumentException("Unknown sink: " + sink);
		};
		String writerClass = switch (implementation) {
		case "baseline" -> WRITER_PACKAGE + "OriginalBinaryQueryResultWriter";
		case "published" -> WRITER_PACKAGE + "PublishedBinaryQueryResultWriter";
		case "current" -> WRITER_PACKAGE + "BinaryQueryResultWriter";
		case "columns" -> WRITER_PACKAGE + "ColumnsBinaryQueryResultWriter";
		case "ascii" -> WRITER_PACKAGE + "AsciiBinaryQueryResultWriter";
		case "reusable" -> WRITER_PACKAGE + "ReusableBinaryQueryResultWriter";
		case "utf8" -> WRITER_PACKAGE + "Utf8BinaryQueryResultWriter";
		case "datatype" -> WRITER_PACKAGE + "DatatypeBinaryQueryResultWriter";
		case "buffered" -> WRITER_PACKAGE + "BufferedBinaryQueryResultWriter";
		case "combined" -> WRITER_PACKAGE + "CombinedBinaryQueryResultWriter";
		default -> implementation.contains(".") ? implementation : WRITER_PACKAGE + implementation;
		};
		constructor = Class.forName(writerClass).asSubclass(TupleQueryResultWriter.class).getConstructor(OutputStream.class);
		if (workload.equals("query")) {
			prepareQuery();
		} else {
			prepareRows();
		}
		// Grow the reusable sink and warm lazy fixture fields before timing; no bytes are discarded by a null sink.
		writeDocument();
	}

	@Benchmark
	@OperationsPerInvocation(ROWS)
	public int serialize(Blackhole blackhole) throws Exception {
		writeDocument();
		blackhole.consume(output.backingArray());
		blackhole.consume(output.sample());
		return output.size();
	}

	private void writeDocument() throws Exception {
		output.reset();
		QueryResponseHeartbeat heartbeat = heartbeatSink ? new QueryResponseHeartbeat(output, () -> {
			throw new AssertionError("The in-memory benchmark sink cannot disconnect");
		}) : null;
		OutputStream target = heartbeat == null ? output : heartbeat.getOutputStream();
		// Reflection is once per complete document, not per row or value. The constructor is resolved at trial setup.
		TupleQueryResultWriter writer = constructor.newInstance(target);
		if (heartbeat != null && heartbeat.start(writer)) {
			heartbeat.close();
			throw new AssertionError("Binary writers must not schedule whitespace heartbeats");
		}
		if (query != null) {
			int count = 0;
			try (TupleQueryResult result = query.evaluate()) {
				writer.startQueryResult(result.getBindingNames());
				while (result.hasNext()) {
					writer.handleSolution(result.next());
					count++;
				}
				writer.endQueryResult();
			}
			if (count != ROWS) {
				throw new IllegalStateException("Expected " + ROWS + " query rows, got " + count);
			}
		} else {
			writer.startQueryResult(names);
			for (BindingSet row : rows) {
				writer.handleSolution(row);
			}
			writer.endQueryResult();
		}
		if (heartbeat != null) {
			heartbeat.complete();
		}
	}

	private void prepareRows() {
		int columns = workload.equals("wide") ? 32 : 8;
		List<String> headers = new ArrayList<>(columns);
		for (int column = 0; column < columns; column++) {
			headers.add("c" + column);
		}
		names = List.copyOf(headers);
		rows = new BindingSet[ROWS];
		Value[][] repeated = workload.equals("repeat_identity") ? new Value[ROWS / REPEAT_RUN][columns] : null;
		String longTail = "a".repeat(8192 - 4);
		String longUnicodeTail = "blåbær-東京-🙂-".repeat(682);
		String latinTail = "æ".repeat(8192 - 4);
		String cjkTail = "東".repeat(8192 - 4);
		String emojiTail = "🙂".repeat((8192 - 4) / 2);
		String sparseTail = "a".repeat(8192 - 5) + "東";
		String mediumTail = "a".repeat(1024 - 4);
		String mediumUnicodeTail = "blåbær-東京-🙂-".repeat(85);
		for (int row = 0; row < ROWS; row++) {
			Value[] values = new Value[columns];
			for (int column = 0; column < columns; column++) {
				values[column] = switch (workload) {
				case "repeat_identity" -> {
					int group = row / REPEAT_RUN;
					if (repeated[group][column] == null) {
						repeated[group][column] = nativeLiteral(group, column, columns);
					}
					yield repeated[group][column];
				}
				case "repeat_equal_lmdb" -> nativeLiteral(row / REPEAT_RUN, column, columns);
				case "unique_lmdb" -> nativeLiteral(row, column, columns);
				case "unicode" -> mixedValue(row, column, true);
				case "long" -> column == 1 ? VF.createLiteral(fourHexDigits(row) + longTail)
						: mixedValue(row, column, false);
				case "long_unicode" -> column == 1 ? VF.createLiteral(fourHexDigits(row) + longUnicodeTail)
						: mixedValue(row, column, true);
				case "long_latin1" -> column == 1 ? VF.createLiteral(fourHexDigits(row) + latinTail)
						: mixedValue(row, column, false);
				case "long_cjk" -> column == 1 ? VF.createLiteral(fourHexDigits(row) + cjkTail)
						: mixedValue(row, column, false);
				case "long_emoji" -> column == 1 ? VF.createLiteral(fourHexDigits(row) + emojiTail)
						: mixedValue(row, column, false);
				case "long_sparse" -> column == 1 ? VF.createLiteral(fourHexDigits(row) + sparseTail)
						: mixedValue(row, column, false);
				case "medium" -> column == 1 ? VF.createLiteral(fourHexDigits(row) + mediumTail)
						: mixedValue(row, column, false);
				case "medium_unicode" -> column == 1 ? VF.createLiteral(fourHexDigits(row) + mediumUnicodeTail)
						: mixedValue(row, column, true);
				default -> mixedValue(row, column, false);
				};
			}
			rows[row] = new ListBindingSet(names, values);
		}
	}

	private static String fourHexDigits(int value) {
		return Integer.toHexString(value | 0x10000).substring(1);
	}

	private static LmdbLiteral nativeLiteral(int row, int column, int columns) {
		long ordinal = 1L + (long) row * columns + column;
		return new LmdbLiteral(SYNTHETIC_REVISION, "native-label-" + row + "-" + column, CoreDatatype.XSD.STRING,
				ValueIds.createCoreLiteralReferenceId(ordinal, CoreDatatype.XSD.STRING));
	}

	private Value mixedValue(int row, int column, boolean unicode) {
		String label = (unicode ? "blåbær-東京-🙂-" : "sample-label-") + row + "-" + column;
		return switch (column & 7) {
		case 0 -> VF.createIRI(NS + "subject:" + row + iriColumnSeparator + column);
		case 1 -> VF.createLiteral(label);
		case 2 -> VF.createLiteral(Integer.toString(row * 31 + column), CoreDatatype.XSD.INTEGER);
		case 3 -> unicode ? VF.createLiteral(label, "ar", Literal.BaseDirection.RTL) : VF.createLiteral(label, "en");
		case 4 -> VF.createBNode("node-" + row + "-" + column);
		case 5 -> VF.createIRI(NS + "kind:" + (row % 17) + iriColumnSeparator + column);
		case 6 -> VF.createLiteral(row + ".125", CoreDatatype.XSD.DECIMAL);
		default -> VF.createLiteral(label, CODE_DATATYPE);
		};
	}

	private void prepareQuery() throws Exception {
		names = QUERY_NAMES;
		directory = Files.createTempDirectory("rdf4j-binary-writer-");
		LmdbStoreConfig config = new LmdbStoreConfig().setNativeEvaluationEnabled(true).setForceSync(false);
		repository = new SailRepository(new LmdbStore(directory.toFile(), config));
		repository.init();
		connection = repository.getConnection();
		connection.begin(IsolationLevels.NONE);
		for (int subject = 0; subject < SUBJECTS; subject++) {
			Value[] first = queryValues(subject, 0);
			IRI s = (IRI) first[0];
			for (int column = 1; column < 7; column++) {
				connection.add(s, VF.createIRI(NS + QUERY_NAMES.get(column)), first[column]);
			}
			for (int value = 0; value < VALUES_PER_SUBJECT; value++) {
				connection.add(s, VF.createIRI(NS + "v"), VF.createLiteral("value-" + value));
			}
		}
		connection.commit();
		query = connection.prepareTupleQuery("PREFIX b: <" + NS + "> "
				+ "SELECT ?s ?label ?kind ?a ?b ?c ?d ?v WHERE { "
				+ "?s b:label ?label; b:kind ?kind; b:a ?a; b:b ?b; b:c ?c; b:d ?d; b:v ?v. }");
	}

	private static Value[] queryValues(int subject, int value) {
		return new Value[] { VF.createIRI(NS + "s:" + subject), VF.createLiteral("subject-" + subject),
				VF.createIRI(NS + "kind:" + (subject % 7)),
				VF.createLiteral(Integer.toString(subject), CoreDatatype.XSD.INTEGER),
				VF.createLiteral("blåbær " + subject, "no"),
				VF.createLiteral(subject + ".125", CoreDatatype.XSD.DECIMAL), VF.createLiteral("payload-" + subject),
				VF.createLiteral("value-" + value) };
	}

	/** Parse the actual complete output and compare every term; deliberately outside JMH's measured operation. */
	public void validateOutput() throws Exception {
		QueryResultCollector collector = new QueryResultCollector();
		BinaryQueryResultParser parser = new BinaryQueryResultParser();
		parser.setQueryResultHandler(collector);
		parser.parseQueryResult(new ByteArrayInputStream(output.backingArray(), 0, output.size()));
		List<BindingSet> parsed = collector.getBindingSets();
		if (parsed.size() != ROWS || !collector.getBindingNames().equals(names)) {
			throw new AssertionError("Invalid output dimensions: " + parsed.size() + " rows, "
					+ collector.getBindingNames());
		}
		boolean[] seen = query == null ? null : new boolean[ROWS];
		for (int row = 0; row < ROWS; row++) {
			BindingSet actual = parsed.get(row);
			BindingSet expected;
			if (query == null) {
				expected = rows[row];
			} else {
				String subjectIri = actual.getValue("s").stringValue();
				String valueLabel = ((Literal) actual.getValue("v")).getLabel();
				if (!subjectIri.startsWith(NS + "s:") || !valueLabel.startsWith("value-")) {
					throw new AssertionError("Unexpected query result identifiers");
				}
				int subject = Integer.parseInt(subjectIri.substring((NS + "s:").length()));
				int value = Integer.parseInt(valueLabel.substring("value-".length()));
				if (subject < 0 || subject >= SUBJECTS || value < 0 || value >= VALUES_PER_SUBJECT) {
					throw new AssertionError("Query result identifier outside fixture range");
				}
				int key = subject * VALUES_PER_SUBJECT + value;
				if (seen[key]) {
					throw new AssertionError("Duplicate query row " + key);
				}
				seen[key] = true;
				expected = new ListBindingSet(names, queryValues(subject, value));
			}
			if (!expected.equals(actual)) {
				throw new AssertionError("Round-trip mismatch at row " + row + ": expected " + expected + ", got "
						+ actual);
			}
		}
	}

	@TearDown(Level.Trial)
	public void tearDown() throws Exception {
		try {
			if (connection != null) {
				connection.close();
			}
		} finally {
			try {
				if (repository != null) {
					repository.shutDown();
				}
			} finally {
				if (directory != null) {
					try (Stream<Path> paths = Files.walk(directory)) {
						for (Path path : paths.sorted(Comparator.reverseOrder()).toList()) {
							Files.delete(path);
						}
					}
				}
			}
		}
	}

	/** Run full parse/term validation: optional CSV lists select implementations, workloads, sinks, and namespaces. */
	public static void main(String[] args) throws Exception {
		String[] implementations = args.length > 0 ? args[0].split(",") : new String[] { "baseline", "current" };
		List<String> workloads = args.length > 1 ? List.of(args[1].split(",")) : WORKLOADS;
		String[] sinks = args.length > 2 ? args[2].split(",") : new String[] { "memory" };
		String[] namespaceLayouts = args.length > 3 ? args[3].split(",") : new String[] { "stable" };
		for (String implementation : implementations) {
			for (String workload : workloads) {
				for (String sink : sinks) {
					for (String namespaceLayout : namespaceLayouts) {
						BinaryWriterBenchmark benchmark = new BinaryWriterBenchmark();
						benchmark.implementation = implementation;
						benchmark.workload = workload;
						benchmark.sink = sink;
						benchmark.namespaceLayout = namespaceLayout;
						try {
							benchmark.setup();
							benchmark.validateOutput();
							System.out.println(implementation + "," + workload + "," + sink + ",namespaceLayout="
									+ namespaceLayout + ",rows=" + ROWS + ",bytes=" + benchmark.output.size()
									+ ",roundtrip=PASS");
						} finally {
							benchmark.tearDown();
						}
					}
				}
			}
		}
	}

	private static final class ReusableOutput extends ByteArrayOutputStream {
		ReusableOutput() {
			super(1 << 20);
		}

		byte[] backingArray() {
			return buf;
		}

		int sample() {
			return count == 0 ? 0 : (buf[count / 4] & 0xff) ^ (buf[count / 2] & 0xff) << 8
					^ (buf[count * 3 / 4] & 0xff) << 16 ^ (buf[count - 1] & 0xff) << 24;
		}
	}

	/** Synthetic initialized models isolate equality overhead; this is explicitly not a real LMDB store. */
	private static final class CanonicalRevision extends ValueStoreRevision.Base {
		@Override
		public long getRevisionId() {
			return 1;
		}

		@Override
		public ValueStore getValueStore() {
			return null;
		}

		@Override
		public boolean resolveValue(long id, LmdbValue value) {
			throw new AssertionError("Synthetic literal payloads must already be initialized");
		}

		@Override
		public boolean hasCanonicalIds() {
			return true;
		}
	}
